import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.Crpw6aS5.js";const k=JSON.parse('{"title":"移动端 Android 客户端","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/index.md","filePath":"mobile/index.md","lastUpdated":1781423278000}'),s={name:"mobile/index.md"};function l(r,t,n,o,h,p){return a(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="移动端-android-客户端" tabindex="-1">移动端 Android 客户端 <a class="header-anchor" href="#移动端-android-客户端" aria-label="Permalink to &quot;移动端 Android 客户端&quot;">​</a></h1><p>EchoFlow Code Mobile 是面向 Android 的远程客户端。它不会在手机上运行 Coding Agent 或桌面 sidecar，而是通过扫码或手动输入连接到已经运行的 EchoFlow Desktop / 本地服务，并在 WebView 中复用现有 H5 聊天界面。</p><p>适合的场景：</p><ul><li>在可信局域网内用手机继续查看会话、发送消息和审批工具权限。</li><li>通过自建 HTTPS 反向代理、VPN、Tailscale、frp 或 Cloudflare Tunnel 远程连接自己的桌面端。</li><li>需要比手机浏览器更顺手的扫码、凭据保存、文件选择、剪贴板和原生权限审批体验。</li></ul><h2 id="能力范围" tabindex="-1">能力范围 <a class="header-anchor" href="#能力范围" aria-label="Permalink to &quot;能力范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>状态</th></tr></thead><tbody><tr><td>Android 原生连接页</td><td>已支持 Server URL + H5 Token</td></tr><tr><td>桌面端二维码</td><td>已支持扫码读取 H5 启动链接</td></tr><tr><td>H5 Token 校验</td><td>打开 WebView 前校验 <code>/health</code> 与 <code>/api/h5-access/verify</code></td></tr><tr><td>凭据保存</td><td>使用 SecureStore 保存已验证连接</td></tr><tr><td>权限审批</td><td>工具权限请求可转发到原生审批弹窗</td></tr><tr><td>文件选择</td><td>WebView 文件输入会调用原生 Document Picker</td></tr><tr><td>剪贴板</td><td>WebView 可通过原生桥接复制/粘贴</td></tr><tr><td>iOS</td><td>暂未做正式发布验证</td></tr><tr><td>手机本地运行 sidecar</td><td>暂不支持</td></tr></tbody></table><h2 id="连接步骤" tabindex="-1">连接步骤 <a class="header-anchor" href="#连接步骤" aria-label="Permalink to &quot;连接步骤&quot;">​</a></h2><ol><li>在电脑上启动 EchoFlow Desktop 或本地服务。</li><li>打开桌面端 <code>设置 -&gt; General -&gt; H5 访问</code>，启用 H5 并生成 Token。</li><li>确保 Android 设备能访问电脑服务，例如在同一可信局域网打开 <code>http://&lt;电脑局域网 IP&gt;:&lt;端口&gt;/health</code>。</li><li>在桌面端复制或展示 H5 扫码启动链接。</li><li>打开 EchoFlow Code Mobile，扫码连接；也可以手动输入 Server URL 和 H5 Token。</li><li>客户端校验成功后进入 H5 WebView，继续使用聊天、工具调用、权限审批和附件能力。</li></ol><p>如果二维码里的 Server URL 是 <code>127.0.0.1</code> 或 <code>localhost</code>，手机无法访问电脑服务。请改用电脑的局域网 IP、VPN 地址或 HTTPS 域名。</p><h2 id="网络建议" tabindex="-1">网络建议 <a class="header-anchor" href="#网络建议" aria-label="Permalink to &quot;网络建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐方式</th></tr></thead><tbody><tr><td>同一 Wi-Fi 测试</td><td>使用电脑局域网 IP + H5 Token</td></tr><tr><td>远程个人使用</td><td>使用 VPN、Tailscale、frp 或 Cloudflare Tunnel</td></tr><tr><td>小团队访问</td><td>使用 HTTPS 反向代理，显式配置允许来源</td></tr><tr><td>公网开放</td><td>不推荐直接暴露；至少使用 HTTPS、强 Token、可信成员和最小来源白名单</td></tr></tbody></table><p>H5 Token 会随 REST 和 WebSocket 请求发送。可信局域网可以临时使用 HTTP；跨公网或不可信网络时，请优先使用 HTTPS。</p><h2 id="本地开发" tabindex="-1">本地开发 <a class="header-anchor" href="#本地开发" aria-label="Permalink to &quot;本地开发&quot;">​</a></h2><p>移动端源码位于 <code>mobile/</code>。MVP 0 推荐使用 JDK 17：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mobile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android</span></span></code></pre></div><p>如果 Windows 上 Expo CLI 在 Bun 下不稳定，可以使用 <code>npx expo start</code> 和 <code>npx expo run:android</code> 作为 fallback。</p><h2 id="和-im-适配器怎么选" tabindex="-1">和 IM 适配器怎么选 <a class="header-anchor" href="#和-im-适配器怎么选" aria-label="Permalink to &quot;和 IM 适配器怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你想要</th><th>推荐入口</th></tr></thead><tbody><tr><td>在手机上看到完整聊天 UI、审批权限、上传文件</td><td>Android 客户端或手机浏览器 H5</td></tr><tr><td>在聊天工具里快速发任务、看进度、停任务</td><td>Telegram / 飞书 / 微信 / 钉钉等 IM 适配器</td></tr><tr><td>团队成员共享入口</td><td>HTTPS 反向代理 + H5 来源白名单，或按 IM 平台做用户配对</td></tr></tbody></table><p>移动端和 IM 不是二选一：Android 客户端适合继续操作同一套 UI，IM 适合轻量命令和异步提醒。</p>`,19)])])}const b=e(s,[["render",l]]);export{k as __pageData,b as default};
